@page "/settings"
@using sv_9dc8ba9d63e74a8880b1361e5dbbc953.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section ? "active" : "")" @onclick="() => ActiveSection = section">
                    @section
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <p>Loading...</p>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfile()
                    break;
                case "Notifications":
                    @RenderNotifications()
                    break;
                case "Security":
                    @RenderSecurity()
                    break;
                case "Appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastType)">@_toastMessage</div>
        }
    </main>
</div>

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string ActiveSection { get; set; } = "Profile";
    private bool _loading = true;

    // Toast
    private string _toastMessage = "";
    private string _toastType = "success";

    // Profile state
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["general", "announcements", "marketing", "engineering", "random"];
    private HashSet<string> _mutedChannels = new();

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string? _revokeSessionId;
    private bool _showRevokeConfirmation;

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = notifs.EmailNotifications;
        _pushNotifications = notifs.PushNotifications;
        _weeklyDigest = notifs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notifs.MutedChannels);

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task ShowToast(string message, string type = "success")
    {
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();
        await Task.Delay(3000);
        _toastMessage = "";
        StateHasChanged();
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _ = ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // Notification methods
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _ = ShowToast("Notification preferences saved!");
    }

    // Security methods
    private async Task UpdatePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            _ = ShowToast("Passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _ = ShowToast("Please fill in all password fields.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _ = ShowToast("Password updated successfully!");
    }

    private void ConfirmRevokeSession(string sessionId)
    {
        _revokeSessionId = sessionId;
        _showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _revokeSessionId = null;
            _showRevokeConfirmation = false;
            _ = ShowToast("Session revoked.");
        }
    }

    private void CancelRevoke()
    {
        _revokeSessionId = null;
        _showRevokeConfirmation = false;
    }

    // Appearance methods
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _ = ShowToast("Appearance settings saved!");
    }

    // Render fragments
    private RenderFragment RenderProfile() => __builder =>
    {
        <h2>Profile</h2>

        <div class="avatar-section">
            <div class="avatar-preview">
                <img src="@_avatarUrl" alt="Avatar" />
            </div>
            <span class="avatar-url">@_avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <h2>Notifications</h2>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>
            <label class="toggle-label">
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>
            <label class="toggle-label">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                var isMuted = _mutedChannels.Contains(channel);
                <label class="channel-item">
                    <input type="checkbox" checked="@isMuted"
                           @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                    <span>#@channel</span>
                </label>
            }
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h2>Security</h2>

        <div class="security-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(_changePasswordExpanded ? "▼" : "▶")</span>
                </button>
                @if (_changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPw">Current Password</label>
                            <input id="currentPw" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPw">New Password</label>
                            <input id="newPw" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPw">Confirm Password</label>
                            <input id="confirmPw" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <label class="toggle-label">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </label>
                @if (_securitySettings?.LastPasswordChange is not null)
                {
                    <p class="meta-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <h3>Active Sessions</h3>
            @if (_securitySettings?.Sessions is not null)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _securitySettings.Sessions.First())
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
        </div>

        @if (_showRevokeConfirmation)
        {
            <div class="modal-overlay">
                <div class="modal">
                    <h3>Confirm Revocation</h3>
                    <p>Are you sure you want to revoke this session? The user will be logged out on that device.</p>
                    <div class="button-group">
                        <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    };

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h2>Appearance</h2>

        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <div class="preview-area @(_theme.ToLower()) @(_fontSize.ToLower()) @(_compactMode ? "compact" : "")">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p><strong>Theme:</strong> @_theme | <strong>Font:</strong> @_fontSize | <strong>Language:</strong> @_language</p>
            <button class="btn-primary">Sample Button</button>
        </div>

        <div class="button-group">
            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };
}

