toolArgs.file_text:
.settings-container {
    display: flex;
    min-height: 80vh;
    max-width: 1100px;
    margin: 2rem auto;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f5f7fa;
    border-right: 1px solid #e0e0e0;
}

.settings-sidebar ul {
    list-style: none;
    margin: 0;
    padding: 1rem 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    font-weight: 500;
    color: #555;
    transition: background 0.2s, color 0.2s;
}

.settings-sidebar li:hover {
    background: #e8ecf1;
}

.settings-sidebar li.active {
    background: #0078d4;
    color: #fff;
}

/* Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
}

.settings-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

/* Forms */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
