+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f5f7fa;
+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #555;
+}
+
+.current-badge {
+    font-size: 0.75rem;
+    background: #e3f2fd;
+    color: #1565c0;
+    padding: 0.2rem 0.5rem;
+    border-radius: 12px;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal {
+    background: #fff;
+    padding: 2rem;
+    border-radius: 8px;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
+}
+
+.modal h3 {
+    margin-top: 0;
+}
+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+.radio-label input[type="radio"] {
+    accent-color: #0078d4;
+}
+
+/* Preview Area */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    transition: all 0.3s ease;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+}
+
+.preview-area.dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-area.light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-area.system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+.preview-area.small {
+    font-size: 0.8rem;
+}
+
+.preview-area.medium {
+    font-size: 1rem;
+}
+
+.preview-area.large {
+    font-size: 1.2rem;
+}
+
+.preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+/* Toast */
+.toast {
+    position: fixed;
+    bottom: 2rem;
+    right: 2rem;
+    padding: 0.75rem 1.5rem;
+    border-radius: 6px;
+    color: #fff;
+    font-size: 0.9rem;
+    z-index: 2000;
+    animation: slideIn 0.3s ease;
+}
+
+.toast.success {
+    background: #388e3c;
+}
+
+.toast.error {
+    background: #d32f2f;
+}
+
+@@keyframes slideIn {
+    from {
+        transform: translateY(20px);
+        opacity: 0;
+    }
+    to {
+        transform: translateY(0);
+        opacity: 1;
+    }
+}
+
+/* Two-factor section */
+.two-factor-section {
+    margin-bottom: 1.5rem;
+}
+
